import { SDK_CODEGEN_VERSION } from '../../ir/schema.js';
import type { SdkIr, SdkProfileAttr, SdkEntity } from '../../ir/schema.js';

const FILE_HEADER = (irVersion: string, generatedAt: string) =>
  `// @bobsled-inc/sdk-codegen codegen_version=${SDK_CODEGEN_VERSION} ir_version=${irVersion}
// AUTO-GENERATED by @bobsled-inc/sdk-codegen.
// Do not edit. Regenerate via \`dogsled sdk generate --lang ts\`.
// IR version: ${irVersion}
// Generated at: ${generatedAt}
`;

const QUALITY_TYPE = `export interface EntityQuality {
  confidence: number;
  freshness_age_seconds: number;
  source_diversity: number;
  profile_coverage: number;
}
`;

function tsTypeFor(attr: SdkProfileAttr): string {
  // Exhaustive switch so adding a new SdkAttrType enum variant in
  // ir/schema.ts is a compile error here, not a silent `unknown` fallthrough.
  let base: string;
  switch (attr.type) {
    case 'string':
    case 'timestamp':
      // Timestamps emit as ISO8601 strings.
      base = 'string';
      break;
    case 'number':
      base = 'number';
      break;
    case 'boolean':
      base = 'boolean';
      break;
    case 'json':
      // JSON values may be objects, arrays, or primitives — `unknown` is
      // the broadest type that still requires the consumer to narrow.
      base = 'unknown';
      break;
    case 'vector':
      // Embedding columns emit as a fixed-length array of floats. The
      // host agent reads `embedded_from` (provider/model/dimension) to generate
      // matching query embeddings.
      base = 'number[]';
      break;
    default: {
      const _exhaustive: never = attr.type;
      throw new Error(`Unhandled SdkAttrType in TypeScript emitter: ${String(_exhaustive)}`);
    }
  }
  return attr.nullable ? `${base} | null` : base;
}

function toPascalIdentifier(value: string): string {
  const parts = value
    .split(/[^a-zA-Z0-9]+/)
    .filter((part) => part.length > 0)
    .map((part) => part[0]!.toUpperCase() + part.slice(1));
  const joined = parts.join('') || 'Entity';
  return /^[0-9]/.test(joined) ? `Entity${joined}` : joined;
}

function profileTypeName(entity: SdkEntity): string {
  return `${toPascalIdentifier(entity.name)}Profile`;
}

function relationshipTypeName(entity: SdkEntity): string {
  return `${toPascalIdentifier(entity.name)}RelationshipName`;
}

function relationshipConstName(entity: SdkEntity): string {
  return `${entity.name.toUpperCase()}_RELATIONSHIPS`.replace(/[^A-Z0-9_]/g, '_');
}

function tsPropertyName(value: string): string {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(value) ? value : JSON.stringify(value);
}

function emitEntity(entity: SdkEntity): string {
  const relationships = [
    ...new Set([...(entity.relationships_as_left ?? []), ...(entity.relationships_as_right ?? [])]),
  ].sort();
  const attrLines = entity.profile_attrs
    .map((attr) => `  ${tsPropertyName(attr.name)}: ${tsTypeFor(attr)};`)
    .join('\n');
  return `import type { EntityQuality } from './_quality.js';

export type ${entity.branded_id_type} = string & { readonly __brand: '${entity.branded_id_type}' };

export const ${relationshipConstName(entity)} = ${JSON.stringify(relationships)} as const;
export type ${relationshipTypeName(entity)} = typeof ${relationshipConstName(entity)}[number];

export interface ${profileTypeName(entity)} {
  ${tsPropertyName(entity.primary_key)}: ${entity.branded_id_type};
${attrLines || '  // (no profile attrs declared)'}
  _quality: EntityQuality;
}
`;
}

// TFilter is constrained to \`object\` (non-primitive) rather than
// \`Record<string, unknown>\` so the strict per-entity FindFilter
// interfaces — which deliberately omit an index signature so users can't
// pass unsupported keys — still satisfy the bound. Dropping \`extends Record<...>\` on the FindFilter
// interfaces requires loosening the upstream constraint here, otherwise
// the emitted client.ts fails \`tsc --noEmit\` with TS2344.
const RUNTIME_SOURCE = `export interface EntityFindRequest<TFilter extends object> {
  entity: string;
  filter: TFilter;
  includes: {
    documents: boolean;
    relationships: string[];
  };
  limit?: number;
  cursor?: string;
}

export interface EntityFindResult<TProfile, TDocument = unknown> {
  profile: TProfile;
  documents: TDocument[];
  relationships: Record<string, unknown[]>;
}

export type EntityMatchMode = 'lookup' | 'assign' | 'stage';

export interface EntityMatchOptions {
  mode?: EntityMatchMode;
}

export interface EntityGetRequest {
  entity: string;
  id: string;
}

export interface EntityMatchRequest<TRecord extends object> {
  entity: string;
  record: TRecord;
  mode?: EntityMatchMode;
}

export interface EntityMatchResult {
  status?: string;
  entity_id?: string;
  record_id?: string;
  idempotency_key?: string;
  band?: string;
  matched_rule?: string;
}

export interface DogsledEntityExecutor {
  find<TProfile, TFilter extends object, TDocument = unknown>(
    request: EntityFindRequest<TFilter>
  ): Promise<Array<EntityFindResult<TProfile, TDocument>>>;
  get?<TProfile>(request: EntityGetRequest): Promise<TProfile | null>;
  match?<TRecord extends object>(
    request: EntityMatchRequest<TRecord>
  ): Promise<EntityMatchResult | null>;
}

export class EntityQueryBuilder<
  TProfile,
  TFilter extends object,
  TDocument = unknown,
  TRelationshipName extends string = string,
> {
  private readonly documents: boolean;
  private readonly relationships: string[];
  private readonly allowedRelationships: readonly string[];
  private readonly maxRows?: number;
  private readonly pageCursor?: string;

  constructor(
    private readonly executor: DogsledEntityExecutor,
    private readonly entity: string,
    private readonly filter: TFilter,
    options: {
      documents?: boolean;
      relationships?: string[];
      allowedRelationships?: readonly string[];
      limit?: number;
      cursor?: string;
    } = {}
  ) {
    this.documents = options.documents ?? false;
    this.relationships = options.relationships ?? [];
    this.allowedRelationships = options.allowedRelationships ?? [];
    this.maxRows = options.limit;
    this.pageCursor = options.cursor;
  }

  withDocuments(): EntityQueryBuilder<TProfile, TFilter, TDocument, TRelationshipName> {
    return new EntityQueryBuilder(this.executor, this.entity, this.filter, {
      documents: true,
      relationships: this.relationships,
      allowedRelationships: this.allowedRelationships,
      limit: this.maxRows,
      cursor: this.pageCursor,
    });
  }

  withRelationship<K extends TRelationshipName>(
    name: K
  ): EntityQueryBuilder<TProfile, TFilter, TDocument, TRelationshipName> {
    if (!this.allowedRelationships.includes(name)) {
      throw new Error(
        'Relationship ' + String(name) + ' is not valid for entity ' + this.entity + '.'
      );
    }
    return new EntityQueryBuilder(this.executor, this.entity, this.filter, {
      documents: this.documents,
      relationships: [...this.relationships, name],
      allowedRelationships: this.allowedRelationships,
      limit: this.maxRows,
      cursor: this.pageCursor,
    });
  }

  limit(n: number): EntityQueryBuilder<TProfile, TFilter, TDocument, TRelationshipName> {
    if (!Number.isInteger(n) || n <= 0) {
      throw new Error('limit(n) requires a positive integer.');
    }
    return new EntityQueryBuilder(this.executor, this.entity, this.filter, {
      documents: this.documents,
      relationships: this.relationships,
      allowedRelationships: this.allowedRelationships,
      limit: n,
      cursor: this.pageCursor,
    });
  }

  after(cursor: string): EntityQueryBuilder<TProfile, TFilter, TDocument, TRelationshipName> {
    if (cursor.trim().length === 0) {
      throw new Error('after(cursor) requires a non-empty cursor.');
    }
    return new EntityQueryBuilder(this.executor, this.entity, this.filter, {
      documents: this.documents,
      relationships: this.relationships,
      allowedRelationships: this.allowedRelationships,
      limit: this.maxRows,
      cursor,
    });
  }

  async all(): Promise<Array<EntityFindResult<TProfile, TDocument>>> {
    return this.executor.find<TProfile, TFilter, TDocument>({
      entity: this.entity,
      filter: this.filter,
      includes: {
        documents: this.documents,
        relationships: this.relationships,
      },
      limit: this.maxRows,
      cursor: this.pageCursor,
    });
  }

  async first(): Promise<EntityFindResult<TProfile, TDocument> | null> {
    const rows = await this.limit(1).all();
    return rows[0] ?? null;
  }
}
`;

function emitClient(ir: SdkIr): string {
  const documentEntity = ir.entities.find((entity) => entity.name.toLowerCase() === 'document');
  const documentType = documentEntity ? profileTypeName(documentEntity) : 'unknown';
  const anyMatch = ir.entities.some((entity) => entity.capabilities.match);
  const typeImports = ir.entities
    .map(
      (entity) =>
        `import type { ${entity.branded_id_type}, ${profileTypeName(entity)}, ${relationshipTypeName(entity)} } from './entities/${entity.name}.js';`
    )
    .join('\n');
  const relationshipImports = ir.entities
    .map(
      (entity) => `import { ${relationshipConstName(entity)} } from './entities/${entity.name}.js';`
    )
    .join('\n');

  const filterTypes = ir.entities
    .map((entity) => {
      const attrs = entity.profile_attrs
        .map(
          (attr) => `  ${tsPropertyName(attr.name)}?: ${tsTypeFor({ ...attr, nullable: true })};`
        )
        .join('\n');
      // Strict shape — no `extends Record<string, unknown>` so users can't
      // accidentally pass unsupported keys. The runtime EntityQueryBuilder
      // / EntityFindRequest / DogsledEntityExecutor type parameters now use
      // `TFilter extends object` (non-primitive) instead of `extends
      // Record<string, unknown>` so these strict per-entity FindFilter
      // interfaces still satisfy the bound.
      return `export interface ${toPascalIdentifier(entity.name)}FindFilter {
  ${tsPropertyName(entity.primary_key)}?: ${entity.branded_id_type};
${attrs || '  // (no profile attrs declared)'}
}`;
    })
    .join('\n\n');

  const entityClients = ir.entities
    .map((entity) => {
      const typeName = toPascalIdentifier(entity.name);
      const matchMethod = entity.capabilities.match
        ? `
  match(record: Partial<${profileTypeName(entity)}>, options?: EntityMatchOptions): Promise<EntityMatchResult | null>;`
        : '';
      return `export interface ${typeName}EntityClient {
  findBy(filter: ${typeName}FindFilter): EntityQueryBuilder<${profileTypeName(entity)}, ${typeName}FindFilter, ${documentType}, ${relationshipTypeName(entity)}>;
  get(id: ${entity.branded_id_type}): Promise<${profileTypeName(entity)} | null>;${matchMethod}
}`;
    })
    .join('\n\n');

  const factoryFunctions = ir.entities
    .map((entity) => {
      const typeName = toPascalIdentifier(entity.name);
      const matchMethod = entity.capabilities.match
        ? `,
    match(record, options = {}) {
      if (!executor.match) throw new Error('DogsledEntityExecutor.match is not implemented.');
      return executor.match({
        entity: ${JSON.stringify(entity.name)},
        record,
        mode: options.mode,
      });
    }`
        : '';
      return `function create${typeName}EntityClient(executor: DogsledEntityExecutor): ${typeName}EntityClient {
  return {
    findBy(filter) {
      return new EntityQueryBuilder<${profileTypeName(entity)}, ${typeName}FindFilter, ${documentType}, ${relationshipTypeName(entity)}>(
        executor,
        ${JSON.stringify(entity.name)},
        filter,
        { allowedRelationships: RELATIONSHIPS_BY_ENTITY[${JSON.stringify(entity.name)}] }
      );
    },
    get(id) {
      if (!executor.get) throw new Error('DogsledEntityExecutor.get is not implemented.');
      return executor.get<${profileTypeName(entity)}>({
        entity: ${JSON.stringify(entity.name)},
        id,
      });
    }${matchMethod},
  };
}`;
    })
    .join('\n\n');

  const dogsledClientFields = ir.entities
    .map(
      (entity) =>
        `    ${tsPropertyName(entity.name)}: ${toPascalIdentifier(entity.name)}EntityClient;`
    )
    .join('\n');
  const dogsledClientFactories = ir.entities
    .map(
      (entity) =>
        `      ${tsPropertyName(entity.name)}: create${toPascalIdentifier(entity.name)}EntityClient(executor),`
    )
    .join('\n');

  const relationshipsByEntity = `export const RELATIONSHIPS_BY_ENTITY = {
${ir.entities
  .map((entity) => `  ${tsPropertyName(entity.name)}: ${relationshipConstName(entity)},`)
  .join('\n')}
} as const;`;

  return `import { EntityQueryBuilder, type DogsledEntityExecutor${anyMatch ? ', type EntityMatchOptions, type EntityMatchResult' : ''} } from './runtime.js';
${typeImports}
${relationshipImports}

${relationshipsByEntity}

${filterTypes}

${entityClients}

${factoryFunctions}

export interface DogsledClient {
  entity: {
${dogsledClientFields}
  };
}

export function createDogsledClient(executor: DogsledEntityExecutor): DogsledClient {
  return {
    entity: {
${dogsledClientFactories}
    },
  };
}
`;
}

export interface EmitTypeScriptOptions {
  /** Override the generated-at timestamp (for deterministic test fixtures). */
  generatedAt?: string;
}

export interface EmittedFile {
  path: string;
  content: string;
}

/**
 * Emit a TypeScript SDK from the SDK IR.
 *
 * Returns a list of files (relative paths). Caller writes them to disk.
 * Generated SDK targets `tsc >=5.0 <5.5`.
 *
 * `EntityQuality` is emitted once into `entities/_quality.ts` and imported
 * by every per-entity file — avoids the TS2308 barrel-collision when
 * `index.ts` re-exports across entities.
 */
export function emitTypeScriptSdk(ir: SdkIr, options: EmitTypeScriptOptions = {}): EmittedFile[] {
  const generatedAt = options.generatedAt ?? new Date().toISOString();
  const header = FILE_HEADER(ir.ir_version, generatedAt);

  const qualityFile: EmittedFile = {
    path: 'entities/_quality.ts',
    content: header + '\n' + QUALITY_TYPE,
  };

  const entityFiles: EmittedFile[] = ir.entities.map((entity) => ({
    path: `entities/${entity.name}.ts`,
    content: header + '\n' + emitEntity(entity),
  }));

  const indexExports = [
    `export type { EntityQuality } from './entities/_quality.js';`,
    `export * from './runtime.js';`,
    `export * from './client.js';`,
    ...ir.entities.map((e) => `export * from './entities/${e.name}.js';`),
  ].join('\n');

  const runtimeFile: EmittedFile = {
    path: 'runtime.ts',
    content: header + '\n' + RUNTIME_SOURCE,
  };

  const clientFile: EmittedFile = {
    path: 'client.ts',
    content: header + '\n' + emitClient(ir),
  };

  const indexFile: EmittedFile = {
    path: 'index.ts',
    content: header + '\n' + indexExports + '\n',
  };

  return [indexFile, runtimeFile, clientFile, qualityFile, ...entityFiles];
}
